<?php declare(strict_types=1); namespace DockerManger; final class Docker { private function run(array $a):array{$c='docker';foreach($a as $v)$c.=' '.escapeshellarg($v);exec($c.' 2>&1',$o,$x);return[$x,implode("\n",$o)];} public function version():string{[$x,$o]=$this->run(['version','--format','{{.Server.Version}}']);return$x===0?trim($o):'Unavailable';} public function containers():array{[$x,$o]=$this->run(['ps','-a','--format','{{json .}}']);$r=[];if(!$x)foreach(preg_split('/\R/',trim($o)) as $l){$j=json_decode($l,true);if(is_array($j))$r[]=$j;}return$r;}}